use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

fn days_in_month(year: u64, month: u64) -> u64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
                29
            } else {
                28
            }
        }
        _ => 30,
    }
}

fn format_date(seconds: u64) -> String {
    let days_total = seconds / 86400;
    let mut year: u64 = 1970;
    let mut remaining_days = days_total;

    loop {
        let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
        let days_in_year = if leap { 366 } else { 365 };
        if remaining_days >= days_in_year {
            remaining_days -= days_in_year;
            year += 1;
        } else {
            break;
        }
    }

    let mut month: u64 = 1;
    loop {
        let dim = days_in_month(year, month);
        if remaining_days >= dim {
            remaining_days -= dim;
            month += 1;
        } else {
            break;
        }
    }

    let day = remaining_days + 1;

    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;

        let query = tick.reason;
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            query
        );
        let _enrichment = http_client::fetch(&url);

        let date = format_date(started);

        RunInfo { date, started }
    }
}

export!(Node);
